import{_ as i,o as a,c as n,a2 as t}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"Wie verwalte ich YAML-Dateien, Zusatzdateien und Backups?","description":"","frontmatter":{"order":4,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/02.anleitungen/04.yaml-dateien.md"},"headers":[],"relativePath":"de/adapter/esphome/anleitungen/yaml-dateien.md","filePath":"de/adapter/esphome/anleitungen/yaml-dateien.md","lastUpdated":1795571670000}'),s={name:"de/adapter/esphome/anleitungen/yaml-dateien.md"};function d(r,e,l,o,h,c){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="wie-verwalte-ich-yaml-dateien-zusatzdateien-und-backups" tabindex="-1">Wie verwalte ich YAML-Dateien, Zusatzdateien und Backups? <a class="header-anchor" href="#wie-verwalte-ich-yaml-dateien-zusatzdateien-und-backups" aria-label="Permalink to &quot;Wie verwalte ich YAML-Dateien, Zusatzdateien und Backups?&quot;">​</a></h1><p><a id="upload-view-delete-yaml-files"></a></p><h2 id="wie-lade-ich-yaml-dateien-hoch-sehe-sie-an-oder-losche-sie" tabindex="-1">Wie lade ich YAML-Dateien hoch, sehe sie an oder lösche sie? <a class="header-anchor" href="#wie-lade-ich-yaml-dateien-hoch-sehe-sie-an-oder-losche-sie" aria-label="Permalink to &quot;Wie lade ich YAML-Dateien hoch, sehe sie an oder lösche sie?&quot;">​</a></h2><p>Das machst du im Reiter „YAML-Dateien“ der Instanzeinstellungen. Die Instanz muss laufen. Die Dateien liegen im Ordner <code>iobroker-data/esphome.&lt;Instanz&gt;</code>, dort liest sie auch das Dashboard.</p><table tabindex="0"><thead><tr><th>Aufgabe</th><th>So geht&#39;s</th></tr></thead><tbody><tr><td>ansehen</td><td>Datei unter „YAML-Datei“ wählen, „In Editor öffnen“. Der Inhalt steht dann unten in „YAML-Inhalt“.</td></tr><tr><td>ändern</td><td>Datei öffnen, „YAML-Inhalt“ ändern, „Datei hochladen“.</td></tr><tr><td>neu anlegen</td><td>„Dateiname (z. B. my-device.yaml)“ und „YAML-Inhalt“ ausfüllen, „Datei hochladen“.</td></tr><tr><td>löschen</td><td>Datei unter „YAML-Datei“ wählen, „Datei löschen“, Rückfrage bestätigen.</td></tr><tr><td>Liste neu laden</td><td>„Dateiliste aktualisieren“</td></tr></tbody></table><p>Der Dateiname muss auf <code>.yaml</code> oder <code>.yml</code> enden und darf keinen Ordner enthalten. „Datei hochladen“ überschreibt eine Datei gleichen Namens ohne Rückfrage, „Datei löschen“ löscht endgültig.</p><p><strong>Siehe auch:</strong> <a href="#fonts-images-include-files-local">Andere Dateien als YAML</a></p><p><a id="fonts-images-include-files-local"></a></p><h2 id="wohin-gehoren-schriften-bilder-include-dateien-und-lokale-external-components" tabindex="-1">Wohin gehören Schriften, Bilder, Include-Dateien und lokale external_components? <a class="header-anchor" href="#wohin-gehoren-schriften-bilder-include-dateien-und-lokale-external-components" aria-label="Permalink to &quot;Wohin gehören Schriften, Bilder, Include-Dateien und lokale external_components?&quot;">​</a></h2><p>Der Reiter „YAML-Dateien“ nimmt nur YAML-Dateien. Schriften, Bilder, Include-Dateien und lokale <code>external_components</code> kopierst du selbst in den Ordner <code>iobroker-data/esphome.&lt;Instanz&gt;</code> auf dem ioBroker-Rechner, gern in Unterordner.</p><p>In der YAML gibst du Pfade relativ zu diesem Ordner an, z. B. <code>fonts/arial.ttf</code>. Die Dateien müssen dem Benutzer gehören, unter dem ioBroker läuft. Hast du als anderer Benutzer kopiert, korrigiert <code>iobroker fix</code> die Rechte.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">font</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;fonts/arial.ttf&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">font_main</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span></span></code></pre></div><p>Mit „Docker-Integration verwenden (Beta)“ liegt der Ordner an derselben Stelle, der Container sieht ihn auch.</p><p><a id="goes-into-secrets-yaml-happens"></a></p><h2 id="was-gehort-in-die-secrets-yaml-und-was-passiert-ohne-sie" tabindex="-1">Was gehört in die secrets.yaml und was passiert ohne sie? <a class="header-anchor" href="#was-gehort-in-die-secrets-yaml-und-was-passiert-ohne-sie" aria-label="Permalink to &quot;Was gehört in die secrets.yaml und was passiert ohne sie?&quot;">​</a></h2><p>In die <code>secrets.yaml</code> gehören Werte, die nicht in jeder Geräte-YAML stehen sollen, z. B. WLAN-Daten und API-Schlüssel. Sie liegt im Ordner <code>iobroker-data/esphome.&lt;Instanz&gt;</code> neben den Geräte-YAMLs. In einer Geräte-YAML holst du einen Wert mit <code>!secret &lt;Name&gt;</code>.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># secrets.yaml</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">wifi_ssid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MeinWLAN&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">wifi_password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;WLAN-Passwort&gt;&quot;</span></span></code></pre></div><p>Der Adapter legt die Datei nicht an. Fehlt sie, scheitert jede YAML, die <code>!secret</code> nutzt, und das Dashboard meldet einen Fehler. Anlegen kannst du sie im Dashboard über „Secrets“ oder im Reiter „YAML-Dateien“ als <code>secrets.yaml</code> hochladen.</p><p><a id="devices-back-into-dashboard-after"></a></p><h2 id="wie-bekomme-ich-meine-gerate-nach-neuinstallation-oder-umzug-wieder-ins-dashboard" tabindex="-1">Wie bekomme ich meine Geräte nach Neuinstallation oder Umzug wieder ins Dashboard? <a class="header-anchor" href="#wie-bekomme-ich-meine-gerate-nach-neuinstallation-oder-umzug-wieder-ins-dashboard" aria-label="Permalink to &quot;Wie bekomme ich meine Geräte nach Neuinstallation oder Umzug wieder ins Dashboard?&quot;">​</a></h2><p>Das Dashboard zeigt genau die YAML-Dateien im Ordner <code>iobroker-data/esphome.&lt;Instanz&gt;</code>. Ist es nach einer Neuinstallation oder einem Umzug leer, fehlen dort die Dateien.</p><ol><li>Kopier die YAML-Dateien und die <code>secrets.yaml</code> aus der Sicherung oder vom alten Rechner in diesen Ordner. Einzelne Dateien kannst du auch im Reiter „YAML-Dateien“ hochladen.</li><li>Gehören die Dateien danach einem anderen Benutzer als ioBroker, führ <code>iobroker fix</code> aus.</li><li>Lade das Dashboard im Browser neu.</li></ol><p>Hast du keine YAML mehr, aber das Gerät läuft noch, zeigt das Dashboard es eventuell mit „Adopt“ an. Damit legt es eine neue YAML an, die du ergänzt.</p><p><strong>Siehe auch:</strong> <a href="#back-up-restore-esphome-files">ESPHome-Dateien sichern</a></p><p><a id="back-up-restore-esphome-files"></a></p><h2 id="wie-sichere-und-stelle-ich-die-esphome-dateien-wieder-her" tabindex="-1">Wie sichere und stelle ich die ESPHome-Dateien wieder her? <a class="header-anchor" href="#wie-sichere-und-stelle-ich-die-esphome-dateien-wieder-her" aria-label="Permalink to &quot;Wie sichere und stelle ich die ESPHome-Dateien wieder her?&quot;">​</a></h2><p>Sichere den Ordner <code>iobroker-data/esphome.&lt;Instanz&gt;</code>. Darin stehen die Geräte-YAMLs, die <code>secrets.yaml</code> und deine eigenen Dateien wie Schriften. Ein Update des Adapters lässt den Ordner stehen.</p><p>BackItUp sichert mit der ESPHome-Option nur die YAML-Dateien. Eigene Dateien wie Schriften, Bilder oder lokale Komponenten sicherst du selbst mit.</p><p>Der Unterordner <code>.esphome</code> enthält Build-Dateien, die ESPHome beim nächsten Kompilieren neu erzeugt. Er wird schnell groß. Lass ihn in der Sicherung weg oder lösch ihn vorher, dann bleibt die Sicherung klein. Mit „Docker-Integration verwenden (Beta)“ liegen die Werkzeuge zum Kompilieren in einem Docker-Volume und nicht in diesem Ordner.</p><p>So stellst du wieder her:</p><ol><li>Stopp die Instanz.</li><li>Kopier den Ordner zurück nach <code>iobroker-data/esphome.&lt;Instanz&gt;</code>.</li><li>Führ <code>iobroker fix</code> aus, damit die Dateien dem ioBroker-Benutzer gehören.</li><li>Start die Instanz.</li></ol><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/installation#adapter-not-installed-compiled-after">Nach einer Wiederherstellung</a></p>`,32)])])}const m=i(s,[["render",d]]);export{u as __pageData,m as default};
